<script>

/\*\*

\* GAME CONFIGURATION & STATE

\*/

const canvas = document.getElementById('game-canvas');

const ctx = canvas.getContext('2d');

const mCanvas = document.getElementById('minimap-canvas');

const mCtx = mCanvas.getContext('2d');



const WORLD\_WIDTH = 3000;

const WORLD\_HEIGHT = 3000;



let gameState = {

paused: false,

scrap: 1000,

camera: { x: 0, y: 0 },

units: \[\],

enemies: \[\],

buildings: \[\],

projectiles: \[\],

particles: \[\],

selectedUnits: \[\],

lastTime: 0,

selectionStart: null,

isDragging: false,

winState: null, // 'win' or 'loss'

wave: 1

};



const UNIT\_TYPES = {

Scout: { hp: 80, speed: 4, range: 150, damage: 8, cooldown: 400, cost: 100, icon: '🏎️', color: '#60a5fa' },

Tank: { hp: 250, speed: 2, range: 200, damage: 25, cooldown: 1200, cost: 250, icon: '🤖', color: '#3b82f6' },

Artillery: { hp: 120, speed: 1.5, range: 500, damage: 60, cooldown: 3000, cost: 400, icon: '🚀', color: '#1d4ed8' },

Trex: { hp: 800, speed: 1.2, range: 60, damage: 40, cooldown: 1000, icon: '🦖', color: '#ef4444' },

Raptor: { hp: 100, speed: 3.5, range: 40, damage: 12, cooldown: 600, icon: '🦎', color: '#f87171' },

Ptero: { hp: 60, speed: 4.5, range: 120, damage: 10, cooldown: 800, icon: '🦅', color: '#fca5a5' }

};



/\*\*

\* CLASSES

\*/



class Entity {

constructor(x, y, type, faction) {

this.x = x;

this.y = y;

this.type = type;

this.faction = faction;

this.stats = { ...UNIT\_TYPES\[type\] };

this.hp = this.stats.hp;

this.targetX = x;

this.targetY = y;

this.radius = 20;

this.lastShot = 0;

this.currentTarget = null;

[this.id](http://this.id) = Math.random().toString(36).substr(2, 9);

}



update(dt) {

// Movement

const dx = this.targetX - this.x;

const dy = this.targetY - this.y;

const dist = Math.sqrt(dx \* dx + dy \* dy);



if (dist > 5) {

this.x += (dx / dist) \* this.stats.speed \* (dt / 16);

this.y += (dy / dist) \* this.stats.speed \* (dt / 16);

}



// AI / Combat

this.findTarget();

if (this.currentTarget) {

const tDist = Math.sqrt(Math.pow(this.currentTarget.x - this.x, 2) + Math.pow(this.currentTarget.y - this.y, 2));

if (tDist <= this.stats.range) {

// Stop to shoot

this.targetX = this.x;

this.targetY = this.y;

this.shoot(this.currentTarget);

} else if (this.faction === 'enemy') {

// Chase

this.targetX = this.currentTarget.x;

this.targetY = this.currentTarget.y;

}

}

}



findTarget() {

if (this.currentTarget && (this.currentTarget.hp <= 0)) this.currentTarget = null;

if (this.currentTarget) return;



const searchList = this.faction === 'player' ? gameState.enemies : \[...gameState.units, ...gameState.buildings\];

let nearest = null;

let minDist = this.stats.range \* 1.5;



for (let e of searchList) {

const d = Math.sqrt(Math.pow(e.x - this.x, 2) + Math.pow(e.y - this.y, 2));

if (d < minDist) {

minDist = d;

nearest = e;

}

}

this.currentTarget = nearest;

}



shoot(target) {

const now = Date.now();

if (now - this.lastShot > this.stats.cooldown) {

gameState.projectiles.push(new Projectile(this.x, this.y, target, this.stats.damage, this.faction));

this.lastShot = now;

}

}



draw() {

const screenX = this.x - gameState.camera.x;

const screenY = this.y - gameState.camera.y;



if (screenX < -50 || screenX > canvas.width + 50 || screenY < -50 || screenY > canvas.height + 50) return;



// Selection ring

if (gameState.selectedUnits.includes(this)) {

ctx.beginPath();

ctx.ellipse(screenX, screenY + 10, 15, 8, 0, 0, Math.PI \* 2);

ctx.strokeStyle = '#00ff00';

ctx.lineWidth = 2;

ctx.stroke();

}



// Body

ctx.font = '24px serif';

ctx.textAlign = 'center';

ctx.textBaseline = 'middle';

ctx.fillText(this.stats.icon, screenX, screenY);



// Health Bar

const hpPercent = this.hp / this.stats.hp;

ctx.fillStyle = '#444';

ctx.fillRect(screenX - 15, screenY - 25, 30, 4);

ctx.fillStyle = hpPercent > 0.5 ? '#2ecc71' : (hpPercent > 0.2 ? '#f1c40f' : '#e74c3c');

ctx.fillRect(screenX - 15, screenY - 25, 30 \* hpPercent, 4);

}

}



class Building extends Entity {

constructor(x, y, type, faction) {

super(x, y, type, faction);

this.radius = 60;

this.stats.hp = type === 'Base' ? 2000 : 1000;

this.hp = this.stats.hp;

}



update(dt) {

if (this.hp < this.stats.hp \* 0.3 && this.type === 'Base' && this.faction === 'player') {

document.getElementById('game-msg').style.opacity = '1';

document.querySelector('.ui-panel').classList.add('base-under-attack');

} else {

document.getElementById('game-msg').style.opacity = '0';

document.querySelector('.ui-panel').classList.remove('base-under-attack');

}

}



