const screenY = this.y - gameState.camera.y;



// Shadow

ctx.fillStyle = 'rgba(0,0,0,0.3)';

ctx.beginPath();

ctx.arc(screenX, screenY + 10, this.radius, 0, Math.PI \* 2);

ctx.fill();



// Building Sprite

ctx.font = '60px serif';

ctx.fillText(this.type === 'Base' ? (this.faction === 'player' ? '🏭' : '🌋') : '🛡️', screenX, screenY);



// Health Bar

const hpPercent = this.hp / this.stats.hp;

ctx.fillStyle = '#444';

ctx.fillRect(screenX - 40, screenY - 60, 80, 8);

ctx.fillStyle = this.faction === 'player' ? '#3b82f6' : '#ef4444';

ctx.fillRect(screenX - 40, screenY - 60, 80 \* hpPercent, 8);

}

}



class Projectile {

constructor(x, y, target, damage, faction) {

this.x = x;

this.y = y;

[this.target](http://this.target) = target;

this.damage = damage;

this.faction = faction;

this.speed = 8;

[this.life](http://this.life) = 100;

}



update() {

if (!this.target || this.target.hp <= 0) {

[this.life](http://this.life) = 0;

return;

}

const dx = this.target.x - this.x;

const dy = this.target.y - this.y;

const dist = Math.sqrt(dx \* dx + dy \* dy);



if (dist < 10) {

this.target.hp -= this.damage;

[this.life](http://this.life) = 0;

createExplosion(this.x, this.y, this.faction === 'player' ? '#60a5fa' : '#ef4444');

} else {

this.x += (dx / dist) \* this.speed;

this.y += (dy / dist) \* this.speed;

}

this.life--;

}



draw() {

const screenX = this.x - gameState.camera.x;

const screenY = this.y - gameState.camera.y;

ctx.fillStyle = this.faction === 'player' ? '#60a5fa' : '#ef4444';

ctx.beginPath();

ctx.arc(screenX, screenY, 3, 0, Math.PI \* 2);

ctx.fill();



// Trail

ctx.strokeStyle = this.faction === 'player' ? 'rgba(96,165,250,0.3)' : 'rgba(239,68,68,0.3)';

ctx.lineWidth = 2;

ctx.beginPath();

ctx.moveTo(screenX, screenY);

ctx.lineTo(screenX - (this.target.x - this.x)\*0.1, screenY - (this.target.y - this.y)\*0.1);

ctx.stroke();

}

}



/\*\*

\* ENGINE FUNCTIONS

\*/



function init() {

window.addEventListener('resize', resize);

resize();



// Create Player Base

gameState.buildings.push(new Building(200, 200, 'Base', 'player'));



// Create Enemy Nest

gameState.buildings.push(new Building(WORLD\_WIDTH - 200, WORLD\_HEIGHT - 200, 'Base', 'enemy'));



// Initial Resources

gameState.scrap = 500;



// Input Listeners

canvas.addEventListener('mousedown', onMouseDown);

window.addEventListener('mousemove', onMouseMove);

window.addEventListener('mouseup', onMouseUp);

canvas.addEventListener('contextmenu', e => e.preventDefault());



// Touch support

canvas.addEventListener('touchstart', (e) => {

const touch = e.touches;

onMouseDown({ clientX: touch.clientX, clientY: touch.clientY, button: 0 });

});

window.addEventListener('touchmove', (e) => {

const touch = e.touches;

onMouseMove({ clientX: touch.clientX, clientY: touch.clientY });

});

window.addEventListener('touchend', (e) => {

onMouseUp({ button: 0 });

});



// Start loop

requestAnimationFrame(gameLoop);



// Passive resource income

setInterval(() => {

if (!gameState.paused) gameState.scrap += 10;

}, 2000);



// Enemy Spawning Logic

setInterval(spawnEnemyWave, 10000);

}



function resize() {

canvas.width = window.innerWidth;

canvas.height = window.innerHeight;

}



function spawnEnemyWave() {

if (gameState.paused || gameState.winState) return;

const nest = gameState.buildings.find(b => b.faction === 'enemy');

if (!nest) return;



const waveSize = 2 + Math.floor(gameState.wave / 2);

for (let i = 0; i < waveSize; i++) {

const type = Math.random() > 0.7 ? 'Trex' : (Math.random() > 0.4 ? 'Raptor' : 'Ptero');

const e = new Entity(nest.x + (Math.random() - 0.5) \* 200, nest.y + (Math.random() - 0.5) \* 200, type, 'enemy');

// Enemies head towards player base

const playerBase = gameState.buildings.find(b => b.faction === 'player');

if (playerBase) {

e.targetX = playerBase.x + (Math.random() - 0.5) \* 100;

e.targetY = playerBase.y + (Math.random() - 0.5) \* 100;

}

gameState.enemies.push(e);

}

gameState.wave++;

}



function createExplosion(x, y, color) {

for (let i = 0; i < 5; i++) {

gameState.particles.push({

x, y,

vx: (Math.random() - 0.5) \* 5,

vy: (Math.random() - 0.5) \* 5,

life: 20,

color: color

});

}

}



/\*\*

\* INPUT HANDLING

\*/



function onMouseDown(e) {

const worldX = e.clientX + gameState.camera.x;

const worldY = e.clientY + gameState.camera.y;



if (e.button === 0) { // Left Click

gameState.isDragging = true;

gameState.selectionStart = { x: e.clientX, y: e.clientY };



// Deselect if not clicking a unit

let clickedUnit = false;

gameState.units.forEach(u => {

const d = Math.sqrt(Math.pow(u.x - worldX, 2) + Math.pow(u.y - worldY, 2));

if (d < u.radius) clickedUnit = true;

});

if (!clickedUnit) {

gameState.selectedUnits = \[\];

updateSelectionUI();

}

} else if (e.button === 2) { // Right Click

// Move selected units

gameState.selectedUnits.forEach((u, i) => {

const row = Math.floor(i / 3);

const col = i % 3;

u.targetX = worldX + (col \* 40) - 40;

u.targetY = worldY + (row \* 40) - 40;

u.currentTarget = null;

});



// Show command feedback

createExplosion(worldX, worldY, '#00ff00');

}

}



function onMouseMove(e) {

if (gameState.isDragging) {

const selBox = document.getElementById('selection-box');

selBox.style.display = 'block';

const left = Math.min(e.clientX, gameState.selectionStart.x);

const top = Math.min(e.clientY, gameState.selectionStart.y);

const width = Math.abs(e.clientX - gameState.selectionStart.x);

const height = Math.abs(e.clientY - gameState.selectionStart.y);

selBox.style.left = left + 'px';

[selBox.style.top](http://selBox.style.top) = top + 'px';

selBox.style.width = width + 'px';

selBox.style.height = height + 'px';

}



// Camera panning at edges

const margin = 50;

if (e.clientX < margin) gameState.camera.x -= 10;

if (e.clientX > canvas.width - margin) gameState.camera.x += 10;

if (e.clientY < margin) gameState.camera.y -= 10;

if (e.clientY > canvas.height - margin) gameState.camera.y += 10;



