 // Constrain camera

gameState.camera.x = Math.max(0, Math.min(gameState.camera.x, WORLD\_WIDTH - canvas.width));

gameState.camera.y = Math.max(0, Math.min(gameState.camera.y, WORLD\_HEIGHT - canvas.height));

