function onMouseUp(e) {

if (gameState.isDragging) {

const selBox = document.getElementById('selection-box');

const rect = selBox.getBoundingClientRect();



if (rect.width > 5 || rect.height > 5) {

gameState.selectedUnits = gameState.units.filter(u => {

const sx = u.x - gameState.camera.x;

const sy = u.y - gameState.camera.y;

return sx >= rect.left && sx <= rect.right && sy >= [rect.top](http://rect.top) && sy <= rect.bottom;

});

} else {

// Single select

const worldX = gameState.selectionStart.x + gameState.camera.x;

const worldY = gameState.selectionStart.y + gameState.camera.y;

const clicked = gameState.units.find(u => {

const d = Math.sqrt(Math.pow(u.x - worldX, 2) + Math.pow(u.y - worldY, 2));

return d < u.radius;

});

if (clicked) gameState.selectedUnits = \[clicked\];

}



selBox.style.display = 'none';

gameState.isDragging = false;

updateSelectionUI();

}

}



function produceUnit(type) {

const cost = UNIT\_TYPES\[type\].cost;

if (gameState.scrap >= cost) {

gameState.scrap -= cost;

const base = gameState.buildings.find(b => b.faction === 'player' && b.type === 'Base');

if (base) {

const u = new Entity(base.x + 80, base.y + 80, type, 'player');

u.targetX = base.x + 150 + (Math.random() \* 100);

u.targetY = base.y + 150 + (Math.random() \* 100);

gameState.units.push(u);

}

}

}



function updateSelectionUI() {

const panel = document.getElementById('selection-panel');

if (gameState.selectedUnits.length > 0) {

panel.classList.remove('hidden');

const u = gameState.selectedUnits;

document.getElementById('selection-icon').innerText = u.stats.icon;

document.getElementById('selection-name').innerText = \`ROBOT ${u.type.toUpperCase()}${gameState.selectedUnits.length > 1 ? 's' : ''}\`;

document.getElementById('selection-hp-bar').style.width = (u.hp / u.stats.hp \* 100) + '%';

} else {

panel.classList.add('hidden');

}

}



function togglePause() {

gameState.paused = !gameState.paused;

document.getElementById('pause-icon').innerHTML = gameState.paused ? 

'<polygon points="5 3 19 12 5 21 5 3"></polygon>' : 

'<rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect>';

}



/\*\*

\* RENDER & LOOP

\*/



function gameLoop(timestamp) {

const dt = timestamp - gameState.lastTime;

gameState.lastTime = timestamp;



if (!gameState.paused) {

update(dt);

}

draw();



if (!gameState.winState) {

requestAnimationFrame(gameLoop);

}

}



function update(dt) {

// Update Units

\[...gameState.units, ...gameState.enemies, ...gameState.buildings\].forEach(u => u.update(dt));



// Clean up dead

gameState.units = gameState.units.filter(u => u.hp > 0);

gameState.enemies = gameState.enemies.filter(e => e.hp > 0);

gameState.buildings = gameState.buildings.filter(b => {

if (b.hp <= 0) {

if (b.type === 'Base') {

checkGameOver(b.faction === 'player' ? 'loss' : 'win');

}

return false;

}

return true;

});



// Update Projectiles

gameState.projectiles.forEach(p => p.update());

gameState.projectiles = gameState.projectiles.filter(p => [p.life](http://p.life) \> 0);



// Update Particles

gameState.particles.forEach(p => {

p.x += p.vx;

p.y += p.vy;

p.life--;

});

gameState.particles = gameState.particles.filter(p => [p.life](http://p.life) \> 0);



// UI counters

document.getElementById('scrap-count').innerText = Math.floor(gameState.scrap);

document.getElementById('enemy-count').innerText = gameState.enemies.length;

}



function draw() {

ctx.clearRect(0, 0, canvas.width, canvas.height);



// Draw Grid

ctx.strokeStyle = '#3d4446';

ctx.lineWidth = 1;

const gridSpacing = 100;

const startX = -(gameState.camera.x % gridSpacing);

const startY = -(gameState.camera.y % gridSpacing);



for (let x = startX; x < canvas.width; x += gridSpacing) {

ctx.beginPath();

ctx.moveTo(x, 0);

ctx.lineTo(x, canvas.height);

ctx.stroke();

}

for (let y = startY; y < canvas.height; y += gridSpacing) {

ctx.beginPath();

ctx.moveTo(0, y);

ctx.lineTo(canvas.width, y);

ctx.stroke();

}



// World bounds

ctx.strokeStyle = '#ef4444';

ctx.lineWidth = 4;

ctx.strokeRect(-gameState.camera.x, -gameState.camera.y, WORLD\_WIDTH, WORLD\_HEIGHT);



// Draw Entities

gameState.buildings.forEach(b => b.draw());

gameState.units.forEach(u => u.draw());

gameState.enemies.forEach(e => e.draw());

gameState.projectiles.forEach(p => p.draw());



// Draw Particles

gameState.particles.forEach(p => {

ctx.fillStyle = p.color;

ctx.globalAlpha = [p.life](http://p.life) / 20;

ctx.fillRect(p.x - gameState.camera.x, p.y - gameState.camera.y, 4, 4);

});

ctx.globalAlpha = 1.0;



drawMinimap();

}



function drawMinimap() {

mCtx.fillStyle = 'rgba(0,0,0,0.5)';

mCtx.fillRect(0, 0, mCanvas.width, mCanvas.height);



const scaleX = mCanvas.width / WORLD\_WIDTH;

const scaleY = mCanvas.height / WORLD\_HEIGHT;



// Player units

mCtx.fillStyle = '#60a5fa';

gameState.units.forEach(u => mCtx.fillRect(u.x \* scaleX, u.y \* scaleY, 3, 3));



// Player Base

const pBase = gameState.buildings.find(b => b.faction === 'player');

if (pBase) {

mCtx.fillStyle = '#3b82f6';

mCtx.fillRect(pBase.x \* scaleX - 4, pBase.y \* scaleY - 4, 8, 8);

}



// Enemies

mCtx.fillStyle = '#ef4444';

gameState.enemies.forEach(e => mCtx.fillRect(e.x \* scaleX, e.y \* scaleY, 3, 3));



// Enemy Nest

const eBase = gameState.buildings.find(b => b.faction === 'enemy');

if (eBase) {

mCtx.fillStyle = '#b91c1c';

mCtx.fillRect(eBase.x \* scaleX - 4, eBase.y \* scaleY - 4, 8, 8);

}



// Viewport

mCtx.strokeStyle = 'white';

mCtx.lineWidth = 1;

mCtx.strokeRect(

gameState.camera.x \* scaleX, 

gameState.camera.y \* scaleY, 

canvas.width \* scaleX, 

canvas.height \* scaleY

);

}



function checkGameOver(result) {

gameState.winState = result;

const modal = document.getElementById('game-over-modal');

const title = document.getElementById('modal-title');

const desc = document.getElementById('modal-desc');



modal.style.display = 'flex';

if (result === 'win') {

title.innerText = 'VICTORY';

title.className = 'text-4xl font-black text-blue-400 mb-4';

desc.innerText = 'The robot revolution has succeeded. The primal threat is neutralized.';

} else {

title.innerText = 'DEFEAT';

title.className = 'text-4xl font-black text-red-500 mb-4';

desc.innerText = 'The mechanical core has been destroyed. Nature has reclaimed the earth.';

}

}



window.onload = init;



</script>



